# srun without the 'no other blender' wait (ws212 Part B export_web is a non-render Blender); gate on MemAvailable only, and refuse if another render runs
cd /workspace/nj-scenes/montclair-state
srun(){ until ! pgrep -f export_web.py >/dev/null && [ $(awk '/MemAvailable/{print int($2/1024)}' /proc/meminfo) -ge ${GATE:-4000} ] && ! pgrep -f "subrend|cutrend|render" -a | grep -v srun216 | grep -q blender; do sleep 2; done; T=$(date +%Y%m%d-%H%M); echo "$(date +%T) $3 $(awk '/MemAvailable/{print int($2/1024)}' /proc/meminfo)"
 FILE=$PWD/$4 CHAIN="${6:-}" CAM="$2" CULL="$1" OUTF=$PWD/renders/$5/${T}_$3.jpg SAMP=${SAMP:-12} PCT=${PCT:-55} WD_MIN=${WDM:-1500} bash scripts/ws33/wd.sh /workspace/opt/blender/blender -b --factory-startup --python scripts/ws212/subrend212.py 2>&1 | grep -E "WROTE|SUB205|F216|F215|F214|F213|F211|Trace|rror|WATCH|MEM189"; }
